import java.io.*;
import java.util.*;

public class Main{
    static long MOD = 998244353;
    static long[] fac;
    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int t = 1;
        while(t-- > 0) {
            int n = sc.nextInt();
            long kk = sc.nextLong();
            fac = new long[n + 1];
            fac[0] = fac[1] = 1L;
            for(int i = 2; i <= n; i++) fac[i] = (fac[i - 1] * i) % MOD;
            if(kk == 0) {
                out.println(fac[n]);
            } else if(kk >= n) {
                out.println(0);
            } else {
                int k = (int) kk;
                long tmp = 0L;
                long sign = 1L;
                int l = n - k;
                int i = 0;
                while(i <= l) {
                    long term = quickPOW(l - i, n) * C(l, l - i) % MOD;
                    tmp = (tmp + MOD + (term * sign) % MOD) % MOD;
                    sign = -sign;
                    i++;
                }
                long res = 2L * C(n, k) % MOD * tmp % MOD;
                out.println(res);
            }
        }
        out.close();
    }
    public static long C(int n, int m) {
        if(m == 0 || m == n) return 1L;
        if(m > n || m < 0) return 0L;
        return fac[n] * quickPOW((fac[m] * fac[n - m]) % MOD, MOD - 2) % MOD;
    }
    public static long quickPOW(long n, long m) {
        long ans = 1L;
        while(m > 0) {
            if((m & 1) == 1) ans = (ans * n) % MOD;
            n = (n * n) % MOD;
            m >>= 1;
        }
        return ans;
    }
    //-----------MyScanner class for faster input----------
    public static class MyScanner {
        BufferedReader br;
        StringTokenizer st;
        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
        long nextLong() {
            return Long.parseLong(next());
        }
        double nextDouble() {
            return Double.parseDouble(next());
        }
        String nextLine(){
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}
